<?php use Namira\Protocol; $prefix=$prefix??'martyr';$terms=Namira\CallUI::terms($db);$militaryVisible=true; ?>
<div class="fields"><?php foreach($defs as $key=>$def): $v=$values[$key]??null;$name=$prefix.'['.$key.']';$fieldId='call_'.substr(hash('sha256',$prefix),0,8).'_'.$key;$military=in_array($key,['service_organization','service_subunit','service_position','service_place'],true); ?>
<div class="field <?= in_array($def['type'],['date','place','textarea','rich'],true)?'full':'' ?>" data-simple-field="<?= e($key) ?>" <?= $military?'data-simple-military'.(!$militaryVisible?' hidden':''):'' ?> <?= $key==='spouse_name'?'data-simple-spouse'.(isset($defs['marital_status'])&&($values['marital_status']??'')!=='married'?' hidden':''):'' ?>>
<input type="hidden" name="<?= e($prefix) ?>[_present][<?= e($key) ?>]" value="1"><label for="<?= $fieldId ?>"><?= e($def['label']) ?></label>
<?php if($def['type']==='date'): $v=is_array($v)?$v:[]; ?>
<fieldset class="protocol-date"><legend class="sr-only"><?= e($def['label']) ?></legend><select id="<?= $fieldId ?>" name="<?= e($name) ?>[calendar]" aria-label="تقویم"><?php foreach(['jalali'=>'شمسی','gregorian'=>'میلادی','hijri'=>'قمری'] as $k=>$label): ?><option value="<?= $k ?>" <?= ($v['calendar']??'jalali')===$k?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select><select name="<?= e($name) ?>[precision]" aria-label="دقت تاریخ"><?php foreach(['unknown'=>'نامشخص','year'=>'فقط سال','month'=>'سال و ماه','day'=>'تاریخ کامل'] as $k=>$label): ?><option value="<?= $k ?>" <?= ($v['precision']??'unknown')===$k?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select><?php foreach(['year'=>'سال','month'=>'ماه','day'=>'روز'] as $k=>$label): ?><input inputmode="numeric" aria-label="<?= $label ?>" placeholder="<?= $label ?>" name="<?= e($name) ?>[<?= $k ?>]" value="<?= e($v[$k]??'') ?>"><?php endforeach ?><input type="hidden" name="<?= e($name) ?>[is_approximate]" value="0"><label><input type="checkbox" name="<?= e($name) ?>[is_approximate]" value="1" <?= !empty($v['is_approximate'])?'checked':'' ?>>تقریبی</label></fieldset>
<?php elseif($def['type']==='place'): $v=is_array($v)?$v:[]; ?>
<fieldset class="protocol-place simple-place"><legend class="sr-only"><?= e($def['label']) ?></legend><div class="fields"><?php foreach(['country_id'=>['country','کشور'],'province_or_state_id'=>['province','استان'],'county_id'=>['county','شهرستان'],'city_or_village_id'=>['city','شهر']] as $part=>$spec): ?><label><?= $spec[1] ?><input type="hidden" data-geo-empty name="<?= e($name) ?>[<?= $part ?>]" value="" disabled><select data-geo-level="<?= $spec[0] ?>" name="<?= e($name) ?>[<?= $part ?>]"><option value="">انتخاب نشده</option><?php foreach($terms as $t):if($t['taxonomy']!==$spec[0]||(!$t['active']&&(string)$t['id']!==(string)($v[$part]??''))||($spec[0]!=='country'&&(string)$t['id']!==(string)($v[$part]??'')))continue; ?><option value="<?= $t['id'] ?>" data-parent="<?= e($t['parent_id']) ?>" <?= (string)($v[$part]??'')===(string)$t['id']?'selected':'' ?>><?= e($t['title']) ?></option><?php endforeach ?></select></label><?php endforeach ?><label>روستا<input name="<?= e($name) ?>[village_name]" value="<?= e($v['village_name']??'') ?>" data-village-input list="<?= $fieldId ?>_villages"></label></div><small class="hint">روستای فاقد گزینه را با نام کامل وارد کنید؛ برای تکمیل فرهنگ محفوظ می‌ماند.</small></fieldset>
<?php elseif(in_array($def['type'],['terms','term'],true)): $taxonomy=$def['options']['taxonomy'];$selected=array_map('strval',(array)$v);$opts=array_filter($terms,fn($t)=>$t['taxonomy']===$taxonomy&&($t['active']||in_array((string)$t['id'],$selected,true))&&!($key==='collections'&&(Protocol::decode($t['metadata'])['mode']??'')==='filter')); ?>
<?php if($def['type']==='terms'): ?><details class="simple-choices" id="<?= $fieldId ?>"><summary>انتخاب <?= e($def['label']) ?> <span data-simple-choice-count></span></summary><div class="simple-choice-options"><?php foreach($opts as $t): ?><label><input type="checkbox" name="<?= e($name) ?>[]" value="<?= $t['id'] ?>" data-military-trigger="<?= !empty(Protocol::decode($t['metadata'])['military_trigger'])?'1':'0' ?>" <?= in_array((string)$t['id'],$selected,true)?'checked':'' ?>><?= e($t['title']) ?></label><?php endforeach ?></div></details>
<?php else: ?><select id="<?= $fieldId ?>" name="<?= e($name) ?>"><option value="">انتخاب نشده</option><?php foreach($opts as $t): ?><option value="<?= $t['id'] ?>" data-parent="<?= e($t['parent_id']) ?>" <?= in_array((string)$t['id'],$selected,true)?'selected':'' ?>><?= e($t['title']) ?></option><?php endforeach ?></select><?php endif ?>
<?php elseif($def['type']==='enum'): ?><select id="<?= $fieldId ?>" name="<?= e($name) ?>"><?php foreach($def['options'] as $k=>$label): ?><option value="<?= e($k) ?>" <?= (string)($v??array_key_first($def['options']))===(string)$k?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select>
<?php elseif(in_array($def['type'],['rich','textarea'],true)): ?><textarea id="<?= $fieldId ?>" name="<?= e($name) ?>" rows="10" dir="rtl" <?= $key==='biography'?'data-simple-rich':'' ?>><?= e($v??'') ?></textarea>
<?php else: ?><input id="<?= $fieldId ?>" name="<?= e($name) ?>" value="<?= e($v??'') ?>" <?= $def['type']==='integer'?'type="number" min="0" step="1"':'' ?> <?= $key==='archive_code'?'dir="ltr" maxlength="80"':'' ?>><?php endif ?>
</div><?php endforeach ?></div>
